/**
 * The Lean-emitted conformance vectors, replayed through the store.
 *
 * `library/cas/vectors/*.json` are generated by executing the Lean
 * model (`lake exe vectors`): store words under scheme-0 SHA-256, one
 * fixture per registered vector plus the `index.json` manifest. This
 * suite is the TypeScript half of the lane: it replays each word
 * binding by binding through the real store (`layerMemoryLive`) and
 * asserts the independently recomputed address of every admitted node
 * equals the Lean-computed one — the whole byte codec and digest
 * pipeline agreeing across the two runtimes.
 *
 * Per the ratified harness rulings: the wire schemas hand-mirror the
 * Lean emitter (the drift tripwire), a decode failure is a red suite,
 * nothing here writes or repairs a fixture, and expectations come from
 * Lean-executed vectors only — never snapshots.
 */
import { expect, it } from "@effect/vitest"
import { Effect, Encoding, Option } from "effect"
import { Cas } from "../src/index.ts"
import { loadVectors } from "./fixtures/vectors.ts"

const { CanonicalSchema, ConformanceVector, Store, layerMemoryLive } = Cas
const { toNodeInput } = ConformanceVector

it.effect("every vector replays: same admission order, same addresses", () =>
  Effect.gen(function* () {
    const { vectors } = yield* loadVectors
    expect(vectors.length).toBeGreaterThan(0)
    for (const vector of vectors) {
      const store = yield* Store
      for (const [position, binding] of vector.word.entries()) {
        const id = yield* store.put(toNodeInput(binding.node))
        expect(`${vector.name}[${position}] ${id}`)
          .toBe(`${vector.name}[${position}] ${binding.address}`)
      }
      // The admitted root reads back byte-identical through the
      // verified load path (canonical decode + recomputed address).
      const rootBinding = vector.word[vector.word.length - 1]!
      const resident = yield* store.load(rootBinding.address)
      expect(Encoding.encodeHex(resident.payload))
        .toBe(Encoding.encodeHex(rootBinding.node.payload))
      expect(resident.refs).toEqual(rootBinding.node.refs)
    }
  }).pipe(Effect.provide(layerMemoryLive)))

it.effect("admission order is semantics: a root put first dangles", () =>
  Effect.gen(function* () {
    const { vectors } = yield* loadVectors
    const referencing = vectors.filter((vector) => vector.word.length > 1)
    expect(referencing.length).toBeGreaterThan(0)
    for (const vector of referencing) {
      const store = yield* Store
      const rootBinding = vector.word[vector.word.length - 1]!
      const refused = yield* Effect.flip(store.put(toNodeInput(rootBinding.node)))
      expect(`${vector.name} ${refused._tag}`)
        .toBe(`${vector.name} CasError/DanglingReference`)
    }
  }).pipe(Effect.provide(layerMemoryLive)))

it("the format carries its canonical, content-addressed identity", () => {
  // The richer wire schema carries the generated schema's native identity.
  expect(Option.getOrThrow(CanonicalSchema.astOf(ConformanceVector.ConformanceVector))._tag)
    .toBe(ConformanceVector.vectorSchema.ast._tag)
  expect(Option.getOrThrow(CanonicalSchema.astOf(ConformanceVector.VectorIndex))._tag)
    .toBe(ConformanceVector.indexSchema.ast._tag)
  // Identity is derived bytes: deterministic, distinct per format.
  const vectorBytes =
    Encoding.encodeHex(CanonicalSchema.bytesOf(ConformanceVector.vectorSchema))
  expect(Encoding.encodeHex(CanonicalSchema.bytesOf(ConformanceVector.ConformanceVector)))
    .toBe(vectorBytes)
  expect(Encoding.encodeHex(CanonicalSchema.bytesOf(ConformanceVector.VectorIndex)))
    .not.toBe(vectorBytes)
})

it.effect("the index manifest tracks the fixtures it names", () =>
  Effect.gen(function* () {
    const { index, vectors } = yield* loadVectors
    expect(index.vectors.length).toBe(vectors.length)
    for (const [position, entry] of index.vectors.entries()) {
      const vector = vectors[position]!
      expect(vector.name).toBe(entry.name)
      expect(vector.word.length).toBe(entry.bindings)
      expect(vector.word[vector.word.length - 1]!.address).toBe(entry.root)
    }
  }))
